import re


_PATTERN = re.compile(
    r"\s*(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?\s*"
)

_MULTIPLIERS = {
    "d": 24 * 60 * 60,
    "h": 60 * 60,
    "m": 60,
    "s": 1,
}


def parse_duration(s):
    """Return the number of seconds represented by a duration string.

    Valid examples include ``"1h30m"``, ``"45s"``, ``"2h5s"`` and
    ``"1d2h"``.  Units must appear at most once, in the order d, h, m, s.
    Invalid input raises :class:`ValueError`.
    """
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    match = _PATTERN.fullmatch(s)
    if match is None:
        raise ValueError(f"invalid duration: {s!r}")

    groups = match.groups()
    if all(amount is None for amount in groups):
        raise ValueError(f"invalid duration: {s!r}")

    total = 0
    for amount, unit in zip(groups, ("d", "h", "m", "s")):
        if amount is not None:
            total += int(amount) * _MULTIPLIERS[unit]
    return total
